// Monta o corpo do report (usado nos 2 ramos) + telefone do lead normalizado.
// Acesso SEGURO em tudo: num parcial as chaves de answers podem nem existir.
const CAMPOS = [["6a8ca7f6793ec7bd4d052629", "Nome do lead"], ["6a8ca82b4db9a913420cef94", "E-mail"], ["6a8ca8134db9a913420cef92", "Instagram"], ["6a8ca8016258782b72093c1c", "Whatsapp"], ["6a8ca8236258782b72093c1e", "Profissão"], ["6a8ca863c1860eea85038603", "Faturamento"], ["6a8ca894f6cfd3dcda07f681", "Objetivo (12 meses)"], ["6a8ca89cc1860eea85038607", "Principal dificuldade hoje"], ["6a8ca8a24db9a913420cef97", "Por que é a oportunidade ideal"], ["6a8ca8a76258782b72093c21", "Por que deveríamos aceitar"], ["6a8dac9562baf5676e073b80", "Pré-aprovação"]];
const resp = $('Trata Webhook').item.json.response || {};
const ans = resp.answers || {};
const val = (id) => {
  const c = ans[id]?.content;
  if (c === null || c === undefined) return '';
  if (c === true) return 'Sim';
  if (c === false) return 'Não';
  return Array.isArray(c) ? c.filter(Boolean).join(', ') : String(c);
};
// Campo vazio não vira linha: no parcial metade das perguntas não existe.
const linhas = CAMPOS.map(([id, rot]) => {
  const v = val(id);
  return v ? `*${rot}*: ${v}` : null;
}).filter(Boolean);
const t = resp.tracking || {};
const utm = ['utm_source', 'utm_campaign', 'utm_medium', 'utm_content', 'utm_term']
  .map((k) => `${k}: ${t[k] || ''}`).join('\n');
const report = linhas.join('\n\n')
  + '\n\n*Origens:*\nFormulário: Forms Rodrigo Guimarães (yay forms)\n\n' + utm;
// Z-API quer só dígitos com DDI; o Yay entrega '+5519971501794'.
let leadPhone = val('6a8ca8016258782b72093c1c').replace(/\D/g, '');
if (leadPhone && !leadPhone.startsWith('55')) leadPhone = '55' + leadPhone;
return [{ json: { ...$json, report, leadPhone } }];

// Link do Calendly do campo 6a8ca8b06258782b72093c23. O Yay grava em 2 formatos:
//   https://calendly.com/scheduled_events/<uuid>/invitees/<uuid>
//   https://calendly.com/app/scheduled_events/user/me?period=all_time&uuid=<uuid>
// Os dois têm que casar — o detector dos funis do JP só pega o primeiro.
const F_CAL = '6a8ca8b06258782b72093c23';
const DESQ = [["6a8ca863c1860eea85038603", ["Até R$ 5.000,00", "R$ 5.000,00 a R$ 10.000,00"], "faturamento"], ["6a8dac9562baf5676e073b80", ["Pode passar minha vaga para outra pessoa, não estou comprometido com meu negócio."], "recusou a vaga (não está comprometido)"]];  // [campo, valores, motivo] — ordem = prioridade do rótulo
const resp = $('Trata Webhook').item.json.response || {};
const ans = resp.answers || {};
const c = ans[F_CAL]?.content;
let eventUuid = null, link = null;
if (typeof c === 'string' && c.includes('calendly.com')) {
  const m = c.match(/scheduled_events\/([0-9a-fA-F-]{36})/) || c.match(/[?&]uuid=([0-9a-fA-F-]{36})/);
  if (m) { eventUuid = m[1]; link = c.trim(); }
}
// Rótulo do report do parcial. Só vale no ramo false (com link, vai pro ramo agendado).
const completa = !!resp.submittedAt;
const regra = DESQ.find(([id, vals]) => vals.includes(ans[id]?.content?.[0] || ''));
const situacao = !completa
  ? 'parcial — abandonou o formulário (não finalizou)'
  : regra
    ? `desqualificado: ${regra[2]} (o form encerra antes do calendário)`
    : 'chegou no calendário e não agendou';
return [{ json: { ...$json, agendou: !!eventUuid, calendlyLink: link, eventUuid, completa, situacao } }];

